source_files.content:
upstream app_backend {
    server 127.0.0.1:8080 max_fails=3 fail_timeout=10s;
    keepalive 32;
}

server {
    listen 80;
    server_name api.platform.com;

    location /api/ {
        proxy_pass http://app_backend;

        # BUG: Disabling proxy buffering forces upstream app servers to hold threads for slow clients
        proxy_buffering off;
        proxy_read_timeout 60s;
        proxy_send_timeout 60s;
    }
}

studio_1_runtime.correct_fix_diff:
- proxy_buffering off;
+ proxy_buffering on;
+ proxy_buffer_size 16k;
+ proxy_buffers 8 64k;
+ proxy_busy_buffers_size 128k;
+ proxy_max_temp_file_size 0; -- Avoid SSD write thrashing if RAM permits
